def solve(xs: list[int]) -> int:
    xs_sorted = sorted(xs, reverse=True)
    n = len(xs_sorted)
    best = None
    prefix = 0
    for i in range(n):
        prefix += xs_sorted[i]
        k = i + 1
        if k % 3 == 2:
            if best is None or prefix > best:
                best = prefix
    return best if best is not None else -1

def solve(xs: list[int]) -> int:
    """Return the length of the longest run of consecutive elements
    that all share the same parity (all even or all odd).
    A single element counts as a run of length 1.
    An empty list has no run, so 0 is returned.
    """
    if not xs:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(xs)):
        if (xs[i] & 1) == (xs[i - 1] & 1):
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 1
    return best
